static String nomDuJour(int jour) {
    return switch (jour) {
        case 1 -> "lundi";
        case 2 -> "mardi";
        case 3 -> "mercredi";
        case 4 -> "jeudi";
        case 5 -> "vendredi";
        case 6 -> "samedi";
        case 7 -> "dimanche";
        default -> "inconnu";
    };
}
